    let mut prerequisites = BTreeSet::new();
    for edge in workspace.graph.dependencies_of(&package.id) {
        if !matches!(
            edge.kind,
            DepKind::Runtime | DepKind::Build | DepKind::Optional | DepKind::Dev
        ) {
            continue;
